<template>
  <a class="skip-link" href="#admin-workspace">跳到运营工作区</a>
  <main id="admin-workspace" class="console" :class="{ 'overview-mode': activeView === 'overview', 'workspace-mode': activeView !== 'overview' }" :aria-busy="loading">
    <header class="console-header">
      <div>
        <p class="eyebrow">运营管理</p>
        <h1>运营工作台</h1>
      </div>
      <div class="header-actions">
        <el-button @click="$router.push('/')">返回主页</el-button>
        <span class="updated" aria-live="polite">数据截至 {{ overview?.generated_at ? formatChinaDateTime(overview.generated_at) : '加载中' }}</span>
        <el-button @click="refresh">刷新态势</el-button>
        <el-button type="primary" @click="$router.push('/admin/operations')">告警与报表</el-button>
      </div>
    </header>

    <nav class="workspace-nav" aria-label="运营工作区">
      <button v-for="item in navItems" :key="item.key" :class="{ active: activeView === item.key }" :aria-current="activeView === item.key ? 'page' : undefined" @click="openView(item.key)">
        <el-icon aria-hidden="true"><component :is="item.icon" /></el-icon><span>{{ item.kicker }}</span>{{ item.label }}
      </button>
    </nav>

    <template v-if="activeView === 'overview'">
      <section class="hero-grid" aria-labelledby="risk-heading">
        <article class="command-card health-card">
          <div class="card-title"><div><p class="card-kicker">当前待办</p><h2 id="risk-heading">{{ actionQueue.length }} 项需要处理</h2></div><el-button link type="primary" @click="$router.push('/admin/operations')">告警规则</el-button></div>
          <ul v-if="actionQueue.length" class="risk-list" aria-label="运营待处理任务">
            <li v-for="item in actionQueue.slice(0, 4)" :key="`${item.kind}-${item.id}`">
              <span class="risk-dot" aria-hidden="true">!</span><div><strong>{{ actionLabel(item) }}</strong><small>{{ item.project_title || '未关联项目' }} · {{ formatChinaDateTime(item.updated_at) }}</small></div>
              <el-button link @click="openProduction(item.id)">处置</el-button>
            </li>
          </ul>
          <p v-else class="quiet-state">暂无卡住或失败的生产任务。</p>
        </article>
        <article class="command-card priority-card">
          <p class="card-kicker">生产状态</p>
          <h2>{{ healthLabel }}</h2>
          <p>{{ healthDescription }}</p>
          <div class="health-stats"><strong>{{ overview?.production?.processing || 0 }}</strong><span>仍在执行的生成与后处理</span></div>
          <el-button link type="primary" @click="drill({ tab: 'production', status: 'processing' })">查看运行中任务</el-button>
        </article>
      </section>

      <section class="metrics" aria-label="关键运营指标">
        <button class="metric-card metric-warning" @click="drill({ tab: 'production', status: 'failed' })"><el-icon aria-hidden="true"><WarningFilled /></el-icon><span>需要处置</span><strong>{{ actionQueue.length }}</strong><small>卡住或失败的任务 →</small></button>
        <button class="metric-card" @click="drill({ tab: 'production', status: 'processing' })"><el-icon aria-hidden="true"><VideoCamera /></el-icon><span>处理中</span><strong>{{ overview?.production?.processing || 0 }}</strong><small>需要持续观察 →</small></button>
        <button class="metric-card" @click="drill({ tab: 'production', status: 'completed' })"><el-icon aria-hidden="true"><CircleCheckFilled /></el-icon><span>已完成</span><strong>{{ overview?.production?.completed || 0 }}</strong><small>查看可交付成片 →</small></button>
        <button class="metric-card" @click="drill({ tab: 'reconciliations', status: 'pending' })"><el-icon aria-hidden="true"><WalletFilled /></el-icon><span>待对账</span><strong>{{ overview?.billing?.pending_reconciliations || 0 }}</strong><small>查看账务处置 →</small></button><button class="metric-card" @click="openView('governance'); governanceTab = 'usage'"><el-icon aria-hidden="true"><WalletFilled /></el-icon><span>已使用积分</span><strong>{{ formatCredits((overview?.billing?.charged_micro || 0) / 10000) }}</strong><small>全部用户累计消耗 →</small></button>
      </section>

      <section class="dashboard-grid">
        <article class="command-card pipeline-card">
          <div class="card-title"><div><p class="card-kicker">生产漏斗</p><h2>生产阶段</h2></div><el-button link @click="openView('production')">生产工作区</el-button></div>
          <ol class="pipeline" aria-label="视频生产阶段漏斗">
            <li v-for="stage in pipeline" :key="stage.key"><div class="pipeline-name"><span>{{ stage.index }}</span><strong>{{ stage.label }}</strong></div><div class="pipeline-bar"><i :style="{ width: `${stage.ratio}%` }" /></div><b>{{ stage.total }}</b><small>{{ stage.detail }}</small></li>
          </ol>
        </article>
        <article class="command-card trend-card">
          <OperationsTrendChart :trend="overview?.trend || []" />
          <div class="trend-actions"><button @click="drill({ tab: 'archives', status: 'failed' })"><b>{{ archiveFailedCount }}</b><span>归档异常</span><small>本地副本仍可用</small></button><button @click="drill({ tab: 'reconciliations', status: 'pending' })"><b>{{ overview?.billing?.pending_reconciliations || 0 }}</b><span>待对账</span><small>核验后结算</small></button></div>
        </article>
      </section>

      <section class="command-card action-board">
        <div><p class="card-kicker">指挥动作</p><h2>运营处置</h2></div>
        <div class="action-grid"><button @click="drill({ tab: 'production', status: 'failed' })"><b>01</b><span>处理失败任务</span><small>只重试失败阶段</small></button><button @click="drill({ tab: 'archives', status: 'failed' })"><b>02</b><span>恢复归档</span><small>保留本地副本</small></button><button @click="drill({ tab: 'reconciliations', status: 'pending' })"><b>03</b><span>处理待对账</span><small>账务保持可审计</small></button></div>
      </section>
    </template>

    <section v-else-if="activeView === 'production'" class="workbench" aria-labelledby="production-heading">
      <div class="workbench-heading"><div><p class="card-kicker">生产任务</p><h2 id="production-heading">AI 生产工作区</h2><p>以异常优先的任务队列处理生成、超分、插帧和归档。</p></div><div class="header-actions"><el-select v-model="filters.production.status" clearable aria-label="筛选生产状态" placeholder="全部状态" @change="loadProduction"><el-option label="处理中" value="processing"/><el-option label="已完成" value="completed"/><el-option label="失败" value="failed"/><el-option label="可重试" value="retryable"/></el-select><el-button @click="loadProduction">刷新队列</el-button><el-button @click="downloadProduction">导出当前筛选</el-button></div></div>
      <div class="queue-summary"><span>队列总数 <b>{{ pages.production.total }}</b></span><span>优先显示最近更新与异常任务</span></div>
      <div class="table-scroll"><el-table :data="production" size="default" row-key="id"><el-table-column prop="id" label="任务" width="88"/><el-table-column prop="username" label="用户" min-width="100"/><el-table-column prop="project_title" label="项目" min-width="130"/><el-table-column prop="model" label="模型" min-width="190" show-overflow-tooltip/><el-table-column label="生产链路" min-width="270"><template #default="{ row }"><div class="stage-chips"><span v-for="stage in row.stages" :key="stage.key" :class="stageTone(stage.status)">{{ stageLabel(stage.key) }} · {{ stage.status }}</span></div></template></el-table-column><el-table-column label="最近更新" width="170"><template #default="{ row }">{{ formatChinaDateTime(row.updated_at) }}</template></el-table-column><el-table-column label="操作" width="88" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openProduction(row.id)">进入</el-button></template></el-table-column></el-table></div>
      <LogPagination :meta="pages.production" @change="changePage('production', $event)" />
    </section>

    <section v-else-if="activeView === 'archives'" class="workbench" aria-labelledby="archive-heading">
      <div class="workbench-heading"><div><p class="card-kicker">媒体归档</p><h2 id="archive-heading">媒体与存储</h2><p>归档失败不等于生产失败；本地可读副本始终优先。</p></div><el-button @click="loadArchives">刷新归档</el-button></div>
      <div class="archive-cards"><article v-for="item in storageSummary" :key="item.status"><span>{{ item.status }}</span><strong>{{ item.count }}</strong></article></div>
      <div class="table-scroll"><el-table :data="archives"><el-table-column prop="id" label="归档 ID" width="90"/><el-table-column prop="local_path" label="本地路径" min-width="260" show-overflow-tooltip/><el-table-column prop="archive_status" label="状态" width="140"/><el-table-column prop="archive_attempts" label="尝试" width="90"/><el-table-column label="更新" width="170"><template #default="{row}">{{ formatChinaDateTime(row.updated_at) }}</template></el-table-column><el-table-column prop="archive_error" label="错误摘要" min-width="200" show-overflow-tooltip/></el-table></div>
      <LogPagination :meta="pages.archives" @change="changePage('archives', $event)" />
    </section>

    <section v-else-if="activeView === 'reconciliations'" class="workbench" aria-labelledby="reconciliation-heading">
      <div class="workbench-heading"><div><p class="card-kicker">计费对账</p><h2 id="reconciliation-heading">待对账队列</h2><p>先验证供应商可核验使用量，再结算或豁免；不在浏览器侧计算积分。</p></div><el-button @click="loadReconciliations">刷新案件</el-button></div>
      <div class="table-scroll"><el-table :data="reconciliations"><el-table-column prop="id" label="案件 ID" min-width="190" show-overflow-tooltip/><el-table-column prop="username" label="用户"/><el-table-column prop="service_type" label="服务"/><el-table-column prop="model" label="模型" min-width="180" show-overflow-tooltip/><el-table-column prop="frozen_amount" label="冻结积分"/><el-table-column prop="status" label="状态"/><el-table-column label="发现时间" min-width="170"><template #default="{row}">{{formatChinaDateTime(row.created_at)}}</template></el-table-column></el-table></div>
      <LogPagination :meta="pages.reconciliations" @change="changePage('reconciliations', $event)" />
    </section>

    <section v-else class="workbench" aria-labelledby="governance-heading">
      <div class="workbench-heading"><div><p class="card-kicker">治理配置</p><h2 id="governance-heading">账户、价目与审计</h2><p>治理配置与历史记录保留在此处，避免干扰生产处置。</p></div></div>
      <el-tabs v-model="governanceTab">
        <el-tab-pane label="用户与余额" name="users">
          <div class="governance-toolbar"><p>创作账号不具备运营后台权限；运营账号单独创建并进入审计记录。</p><el-button type="primary" @click="showCreate = true">新建账号</el-button></div>
          <div class="table-scroll"><el-table :data="users"><el-table-column prop="username" label="用户"/><el-table-column prop="display_name" label="显示名"/><el-table-column label="账号类型"><template #default="{row}">{{ row.account_kind === 'platform_admin' ? '运营后台账号' : '创作账号' }}</template></el-table-column><el-table-column label="项目分组" min-width="140"><template #default="{row}">{{ row.tenant_name || '未分组' }}</template></el-table-column><el-table-column prop="balance" label="余额"/><el-table-column prop="frozen" label="冻结"/><el-table-column prop="total_consumed" label="已使用"/><el-table-column label="操作" width="165" fixed="right"><template #default="{ row }"><el-button link @click="openUserGroup(row)">分组</el-button><el-button link class="balance-adjust-action" @click="openBalance(row)">调整积分</el-button></template></el-table-column></el-table></div>
        </el-tab-pane>
        <el-tab-pane label="项目分组" name="tenants"><div class="governance-toolbar"><p>每个分组拥有独立 API、默认模型与 SD2 认证；成员只使用配置，不能查看密钥。</p><el-button type="primary" @click="openTenant()">新建分组</el-button></div><div class="table-scroll"><el-table :data="tenants"><el-table-column prop="name" label="分组" min-width="150"/><el-table-column prop="member_count" label="成员" width="90"/><el-table-column prop="price_book_name" label="共享价目表" min-width="200"/><el-table-column label="配置范围" min-width="220"><template #default="{row}">独立 API、默认路由、SD2、价目表</template></el-table-column><el-table-column label="操作" width="205" fixed="right"><template #default="{row}"><el-button link @click="openTenant(row.id)">编辑</el-button><el-button link type="primary" @click="openTenantConfigs(row)">AI / SD2 配置</el-button><el-button link @click="openTenant(row.id)">价目</el-button></template></el-table-column></el-table></div></el-tab-pane>
        <el-tab-pane label="价目表" name="prices"><div class="governance-toolbar"><p>价目表变更为后续调用保留独立版本。</p><el-button type="primary" @click="openPrice()">新建价目表</el-button></div><el-collapse><el-collapse-item v-for="book in books" :key="book.id" :title="`${book.name} · ${book.status}`"><template #title><span>{{ book.name }} · {{ book.status }}</span><el-button link type="primary" @click.stop="openPrice(book)">编辑</el-button></template><div class="table-scroll"><el-table :data="book.items"><el-table-column prop="service_type" label="服务"/><el-table-column prop="model" label="模型"/><el-table-column prop="meter" label="计量"/><el-table-column prop="unit_price" label="积分单价"/></el-table></div></el-collapse-item></el-collapse></el-tab-pane>
        <el-tab-pane label="资金流水" name="transactions"><div class="billing-filters"><el-date-picker v-model="filters.billing.dates" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="按日期筛选资金流水" @change="reloadBilling"/><el-select v-model="filters.billing.role" clearable placeholder="全部角色" aria-label="按角色筛选资金流水" @change="onBillingRoleChange"><el-option label="管理员" value="admin"/><el-option label="普通用户" value="user"/></el-select><el-select v-model="filters.billing.tenant_id" clearable placeholder="全部分组" aria-label="按分组筛选资金流水" @change="reloadBilling"><el-option label="未分组" :value="0"/><el-option v-for="tenant in tenants" :key="tenant.id" :label="tenant.name" :value="tenant.id"/></el-select><el-select v-model="filters.billing.user_id" clearable filterable placeholder="全部用户" aria-label="按具体用户筛选资金流水" @change="reloadBilling"><el-option v-for="user in filteredBillingUsers" :key="user.id" :label="billingUserLabel(user)" :value="user.id"/></el-select><el-button text @click="clearBillingFilters">清除筛选</el-button></div><BillingTransactionTable :rows="transactions" show-user :total="pages.transactions.total" :page="pages.transactions.page" :page-size="pages.transactions.page_size" @page-change="changePage('transactions', $event)" /></el-tab-pane>
        <el-tab-pane label="模型用量" name="usage"><div class="billing-filter-note">沿用资金流水的日期、角色和用户筛选。</div><div class="table-scroll"><el-table :data="usage"><el-table-column label="时间" min-width="170"><template #default="{row}">{{formatChinaDateTime(row.created_at)}}</template></el-table-column><el-table-column prop="username" label="用户"/><el-table-column label="分组" width="110"><template #default="{row}">{{ row.tenant_name || '—' }}</template></el-table-column><el-table-column prop="role" label="角色"/><el-table-column prop="service_type" label="服务"/><el-table-column prop="model" label="模型"/><el-table-column prop="charged" label="积分"/></el-table></div><LogPagination :meta="pages.usage" @change="changePage('usage',$event)"/></el-tab-pane>
        <el-tab-pane label="审计" name="audit"><div class="table-scroll"><el-table :data="audits"><el-table-column label="时间" min-width="170"><template #default="{row}">{{formatChinaDateTime(row.created_at)}}</template></el-table-column><el-table-column prop="actor_username" label="操作者"/><el-table-column prop="action" label="操作"/><el-table-column prop="target_type" label="对象"/></el-table></div><LogPagination :meta="pages.audit" @change="changePage('audit',$event)"/></el-tab-pane>
      </el-tabs>
    </section>

    <el-drawer v-model="showProduction" title="生产任务处置" size="min(520px, 94vw)"><template v-if="productionDetail"><p class="drawer-title">任务 #{{ productionDetail.id }} · {{ productionDetail.status }}</p><p class="drawer-total-time">总耗时：{{ productionTotalElapsed(productionDetail) }}</p><el-timeline><el-timeline-item v-for="stage in productionDetail.stages" :key="stage.key" :timestamp="formatChinaDateTime(stage.updated_at)"><strong>{{ stageLabel(stage.key) }}</strong> · {{ stage.status }}<small v-if="stage.message">{{ stage.message }}</small><small v-if="stage.elapsed_ms !== null">阶段耗时：{{ formatElapsed(stage.elapsed_ms) }}</small><small v-if="stage.provider_task_id">供应商任务：{{ stage.provider_task_id }}</small></el-timeline-item></el-timeline><article class="drawer-fact"><span>错误摘要</span><p>{{ productionDetail.error_summary || '无' }}</p></article><article class="drawer-fact"><span>本地路径</span><p>{{ productionDetail.local_path || '未持久化' }}</p></article><div class="drawer-actions"><el-button v-if="productionDetail.omni_job_id && productionDetail.upscale_status === 'failed'" @click="handleProductionAction('upscale')">仅重试超分</el-button><el-button v-if="productionDetail.omni_job_id && productionDetail.interpolation_status === 'failed'" @click="handleProductionAction('interpolation')">仅重试插帧</el-button><el-button v-if="canAdoptSource" @click="handleProductionAction('adopt')">采用原片</el-button><el-button v-if="productionDetail.local_path && productionDetail.archive_status !== 'oss_synced'" @click="handleProductionAction('archive')">仅重试 OSS</el-button></div></template></el-drawer>
    <el-dialog v-model="showCreate" title="新建账号" width="min(480px, 94vw)"><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="newUser.username" autocomplete="off"/></el-form-item><el-form-item label="显示名"><el-input v-model="newUser.display_name"/></el-form-item><el-form-item label="初始密码"><el-input v-model="newUser.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="账号类型"><el-radio-group v-model="newUser.account_kind"><el-radio-button value="creator">创作账号</el-radio-button><el-radio-button value="platform_admin">运营后台账号</el-radio-button></el-radio-group></el-form-item><el-form-item label="项目分组"><el-select v-model="newUser.tenant_id" style="width:100%"><el-option v-for="tenant in activeTenants" :key="tenant.id" :label="tenant.name" :value="tenant.id"/></el-select><p class="tenant-help">账号余额保持为 0；成员调用扣个人余额，使用所选分组绑定的 API 与价目表。</p></el-form-item></el-form><template #footer><el-button @click="showCreate = false">取消</el-button><el-button type="primary" @click="createUser">创建</el-button></template></el-dialog>
    <el-dialog v-model="showUserGroup" title="调整用户分组" width="min(440px, 94vw)"><el-form label-position="top"><el-form-item label="用户"><el-input :model-value="selected?.display_name || selected?.username" disabled/></el-form-item><el-form-item label="项目分组"><el-select v-model="userGroup.tenant_id" style="width:100%"><el-option v-for="tenant in activeTenants" :key="tenant.id" :label="tenant.name" :value="tenant.id"/></el-select></el-form-item><el-form-item label="组内角色"><el-radio-group v-model="userGroup.role"><el-radio-button value="creator">成员</el-radio-button><el-radio-button value="tenant_admin">组管理员</el-radio-button></el-radio-group></el-form-item><p class="tenant-help">调整后仅影响后续调用可用的 API、SD2 认证和价目表；个人余额、历史账本、项目和任务不迁移。</p></el-form><template #footer><el-button @click="showUserGroup = false">取消</el-button><el-button type="primary" @click="saveUserGroup">保存分组</el-button></template></el-dialog>
    <el-dialog v-model="showTenant" class="tenant-dialog" :title="tenantForm.id ? '编辑项目分组' : '新建项目分组'" width="min(560px, 94vw)"><el-form label-position="top"><el-form-item label="分组名称"><el-input v-model="tenantForm.name"/></el-form-item><el-form-item v-if="tenantForm.id" label="共享价目表"><el-select v-model="tenantForm.price_book_id" clearable style="width:100%"><el-option v-for="book in publishedBooks" :key="book.id" :label="book.name" :value="book.id"/></el-select><p class="tenant-help">AI、默认模型与 SD2 认证请通过“AI / SD2 配置”维护；保存价目不会改动这些配置。</p></el-form-item></el-form><template #footer><el-button @click="showTenant = false">取消</el-button><el-button type="primary" @click="saveTenant">保存</el-button></template></el-dialog>
    <el-dialog v-model="showTenantConfigs" class="tenant-config-dialog" :title="`${configTenant?.name || ''} · AI 与 SD2 配置`" width="min(1180px, 96vw)" destroy-on-close><AIConfigContent v-if="configTenant" :tenant-id="configTenant.id" :tenant-name="configTenant.name" /></el-dialog>
    <el-dialog v-model="showBalance" title="调整账户积分" width="min(500px, 94vw)"><el-form label-position="top"><el-form-item label="方式"><el-radio-group v-model="balance.mode"><el-radio-button value="adjust">增减</el-radio-button><el-radio-button value="correct">校正到</el-radio-button></el-radio-group></el-form-item><el-form-item :label="balance.mode === 'adjust' ? '变动积分（可为负数）' : '目标积分余额'"><el-input-number v-model="balanceValue" :precision="2" :step="10"/></el-form-item><el-form-item label="情况说明（选填）"><el-input v-model="balance.reason" type="textarea" :rows="3" maxlength="200" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="showBalance = false">取消</el-button><el-button type="primary" @click="adjustBalance">确认调整</el-button></template></el-dialog>
    <el-dialog v-model="showPrice" :title="editingPriceId ? '编辑价目表' : '新建价目表'" width="min(680px, 94vw)"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="price.name"/></el-form-item><el-form-item label="状态"><el-select v-model="price.status"><el-option label="草稿" value="draft"/><el-option label="已发布" value="published"/><el-option label="已归档" value="archived"/></el-select></el-form-item><div v-for="(item, index) in price.items" :key="index" class="price-item"><el-select v-model="item.service_type"><el-option label="图片" value="image"/><el-option label="视频" value="video"/><el-option label="文本" value="text"/></el-select><el-input v-model="item.model" placeholder="模型"/><el-select v-model="item.meter"><el-option v-for="meter in meters" :key="meter" :label="meter" :value="meter"/></el-select><el-input-number v-model="item.unit_price" :min="0" :precision="4"/><el-button link type="danger" @click="price.items.splice(index, 1)">删除</el-button></div><el-button @click="addPriceItem">添加计价项</el-button></el-form><template #footer><el-button @click="showPrice = false">取消</el-button><el-button type="primary" @click="savePrice">保存</el-button></template></el-dialog>
  </main>
</template>

<script setup>
import { computed, defineComponent, h, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox, ElPagination } from 'element-plus'
import { CircleCheckFilled, PictureFilled, Setting, VideoCamera, WalletFilled, WarningFilled } from '@element-plus/icons-vue'
import { adminAPI } from '@/api/account'
import request from '@/utils/request'
import BillingTransactionTable from '@/components/BillingTransactionTable.vue'
import { formatCredits } from '@/utils/billingPresentation'
import OperationsTrendChart from '@/components/OperationsTrendChart.vue'
import { formatChinaDateTime } from '@/utils/time'
import { createClientRequestId } from '@/utils/requestId'
import AIConfigContent from '@/components/AIConfigContent.vue'

const route = useRoute(); const router = useRouter()
const validViews = ['overview', 'production', 'archives', 'reconciliations', 'governance']
const activeView = ref(validViews.includes(route.query.tab) ? route.query.tab : 'overview')
const governanceTab = ref(route.query.settings === 'tenants' ? 'tenants' : 'users'); const loading = ref(false); const overview = ref(null)
const production = ref([]); const archives = ref([]); const reconciliations = ref([]); const users = ref([]); const books = ref([]); const tenants = ref([]); const availableConfigs = ref([]); const transactions = ref([]); const usage = ref([]); const audits = ref([])
const productionDetail = ref(null); const showProduction = ref(false)
const showCreate = ref(false); const showBalance = ref(false); const showPrice = ref(false); const showTenant = ref(false); const showTenantConfigs = ref(false); const showUserGroup = ref(false); const selected = ref(null); const configTenant = ref(null); const editingPriceId = ref(null)
const newUser = reactive({ username: '', display_name: '', password: '', account_kind: 'creator', tenant_id: null })
const userGroup = reactive({ tenant_id: null, role: 'creator' })
const tenantForm = reactive({ id: null, name: '', ai_config_ids: [], default_config_ids: {}, sd2_config_ids: [], price_book_id: null })
const balance = reactive({ mode: 'adjust', amount_credits: 0, target_credits: 0, reason: '' })
const balanceValue = computed({ get: () => balance.mode === 'adjust' ? balance.amount_credits : balance.target_credits, set: (value) => { if (balance.mode === 'adjust') balance.amount_credits = value; else balance.target_credits = value } })
const price = reactive({ name: '', status: 'draft', items: [] }); const meters = ['image', 'second', 'character', 'token', 'request']
const filters = reactive({ production: { status: route.query.status || '', model: route.query.model || '' }, billing: { dates: [], role: '', user_id: null, tenant_id: null } })
const pages = reactive({ production: { page: 1, page_size: 20, total: 0 }, archives: { page: 1, page_size: 20, total: 0 }, reconciliations: { page: 1, page_size: 20, total: 0 }, transactions: { page: 1, page_size: 20, total: 0 }, usage: { page: 1, page_size: 20, total: 0 }, audit: { page: 1, page_size: 20, total: 0 } })
const navItems = [{ key: 'overview', kicker: '01', label: '概览', icon: CircleCheckFilled }, { key: 'production', kicker: '02', label: '生产', icon: VideoCamera }, { key: 'archives', kicker: '03', label: '媒体', icon: PictureFilled }, { key: 'reconciliations', kicker: '04', label: '对账', icon: WalletFilled }, { key: 'governance', kicker: '05', label: '设置', icon: Setting }]
const LogPagination = defineComponent({ props: { meta: { type: Object, required: true } }, emits: ['change'], setup(props, { emit }) { return () => props.meta.total > props.meta.page_size ? h(ElPagination, { class: 'log-pagination', background: true, layout: 'prev, pager, next, total', currentPage: props.meta.page, pageSize: props.meta.page_size, total: props.meta.total, onCurrentChange: (page) => emit('change', page) }) : null } })
const failedAndRetryable = computed(() => Number(overview.value?.production?.failed || 0) + Number(overview.value?.production?.retryable || 0))
const actionQueue = computed(() => overview.value?.action_queue || [])
const archiveFailedCount = computed(() => Number((overview.value?.storage || []).find((item) => item.status === 'failed')?.count || 0))
const healthLabel = computed(() => actionQueue.value.length || failedAndRetryable.value || overview.value?.alerts?.length ? '需要关注' : '运行平稳')
const healthDescription = computed(() => failedAndRetryable.value ? `${failedAndRetryable.value} 个失败或可重试任务等待处理。` : '当前没有阻断生产的风险信号。')
const storageSummary = computed(() => overview.value?.storage || [])
const trendMax = computed(() => Math.max(1, ...(overview.value?.trend || []).map((day) => Number(day.total || 0))))
const trendDescription = computed(() => `近七日生产创建和完成趋势，最高单日创建 ${trendMax.value} 条`)
const pipeline = computed(() => {
  const summary = overview.value?.stage_summary || {}; const base = Math.max(1, Number(summary.generation?.completed || 0));
  return [{ key: 'generation', index: '01', label: '生成', total: summary.generation?.completed || 0, detail: `进行中 ${summary.generation?.active || 0}`, ratio: 100 }, { key: 'upscale', index: '02', label: '超分', total: summary.upscale?.completed || 0, detail: `异常 ${summary.upscale?.failed || 0}`, ratio: Math.min(100, Math.round(Number(summary.upscale?.completed || 0) / base * 100)) }, { key: 'interpolation', index: '03', label: '插帧', total: summary.interpolation?.completed || 0, detail: `异常 ${summary.interpolation?.failed || 0}`, ratio: Math.min(100, Math.round(Number(summary.interpolation?.completed || 0) / base * 100)) }, { key: 'archive', index: '04', label: '归档', total: summary.archive?.completed || 0, detail: `待处理 ${summary.archive?.active || 0}`, ratio: Math.min(100, Math.round(Number(summary.archive?.completed || 0) / base * 100)) }]
})
const canAdoptSource = computed(() => productionDetail.value?.omni_job_id && ['failed', 'cancelled', 'reconciliation_required'].includes(productionDetail.value.upscale_status || '') || productionDetail.value?.omni_job_id && ['failed', 'cancelled', 'reconciliation_required'].includes(productionDetail.value.interpolation_status || ''))

function applyPage(target, name, result) { target.value = result.items || []; Object.assign(pages[name], { page: result.page || 1, page_size: result.page_size || 20, total: result.total || 0 }) }
function barHeight(value) { return Math.max(3, Math.round(Number(value || 0) / trendMax.value * 100)) }
function stageLabel(key) { return ({ generation: '生成', upscale: '超分', interpolation: '插帧', archive: '归档' })[key] || key }
function formatElapsed(value) { const seconds = Math.max(0, Math.floor(Number(value || 0) / 1000)); return seconds >= 60 ? `${Math.floor(seconds / 60)} 分 ${seconds % 60} 秒` : `${seconds} 秒` }
function productionTotalElapsed(row) { if (!row || !row.created_at) return '—'; const end = row.updated_at || row.created_at; const ms = Date.parse(end) - Date.parse(row.created_at); return Number.isFinite(ms) && ms >= 0 ? formatElapsed(ms) : '—' }
function stageTone(status) { return ['failed', 'retryable', 'invalid', 'cancelled'].includes(status) ? 'bad' : ['completed', 'oss_synced'].includes(status) ? 'good' : 'neutral' }
function alertText(alert) { return ({ stale_production: '生产任务长时间未更新', continuous_failures: `模型连续失败${alert.model ? `：${alert.model}` : ''}`, pending_reconciliation: '存在待对账案件', archive_failed: '存在归档失败' })[alert.key] || alert.key }
function actionLabel(item) { return item.kind === 'stalled' ? `任务 #${item.id} 长时间未更新` : `任务 #${item.id} ${item.status === 'failed' ? '生成失败' : '可重试'}` }
function syncRoute() { router.replace({ query: { ...route.query, tab: activeView.value, ...(filters.production.status ? { status: filters.production.status } : {}), ...(filters.production.model ? { model: filters.production.model } : {}) } }) }
async function refresh() { loading.value = true; try { overview.value = await adminAPI.overview() } finally { loading.value = false } }
async function loadProduction() { await refresh(); applyPage(production, 'production', await adminAPI.production({ ...pages.production, ...filters.production })) }
async function loadArchives() { await refresh(); applyPage(archives, 'archives', await adminAPI.mediaArchives(pages.archives)) }
async function loadReconciliations() { await refresh(); applyPage(reconciliations, 'reconciliations', await adminAPI.reconciliations(pages.reconciliations)) }
const filteredBillingUsers = computed(() => users.value.filter((user) => !filters.billing.role || user.role === filters.billing.role))
const sd2Configs = computed(() => availableConfigs.value.filter((config) => ['jimeng2_character_auth', 'model_ark_asset'].includes(config.service_type)))
const publishedBooks = computed(() => books.value.filter((book) => book.status === 'published'))
const activeTenants = computed(() => tenants.value.filter((tenant) => tenant.status === 'active'))
const selectedConfigGroups = computed(() => {
  const groups = new Map()
  for (const config of availableConfigs.value.filter((item) => tenantForm.ai_config_ids.includes(item.id))) {
    const list = groups.get(config.service_type) || []
    list.push(config); groups.set(config.service_type, list)
  }
  return [...groups.entries()].map(([service_type, configs]) => ({ service_type, configs }))
})
function serviceLabel(type) { return ({ text: '文本', image: '图片', storyboard_image: '分镜图片', video: '视频', video_postprocess: '视频后处理', tts: '语音', jimeng2_character_auth: '角色认证', model_ark_asset: '素材认证' })[type] || type }
function ensureTenantDefaults() { const selected = new Set(tenantForm.ai_config_ids); for (const group of selectedConfigGroups.value) { if (!selected.has(tenantForm.default_config_ids[group.service_type])) tenantForm.default_config_ids[group.service_type] = group.configs[0].id } for (const type of Object.keys(tenantForm.default_config_ids)) { if (!selectedConfigGroups.value.some((group) => group.service_type === type)) delete tenantForm.default_config_ids[type] } }
function billingUserLabel(user) { return `${user.display_name || user.username}（${user.username} · ${user.role === 'admin' ? '管理员' : '普通用户'}）` }
function billingFilterParams(page) { const [date_from, date_to] = filters.billing.dates || []; return { ...page, ...(date_from ? { date_from } : {}), ...(date_to ? { date_to } : {}), ...(filters.billing.role ? { role: filters.billing.role } : {}), ...(filters.billing.user_id ? { user_id: filters.billing.user_id } : {}), ...((filters.billing.tenant_id === 0 || filters.billing.tenant_id) ? { tenant_id: filters.billing.tenant_id } : {}) } }
async function loadGovernance() { const [nextUsers, nextBooks, nextTenants, nextConfigs, nextTransactions, nextUsage, nextAudit] = await Promise.all([adminAPI.users(), adminAPI.priceBooks(), adminAPI.tenants(), request.get('/ai-configs'), adminAPI.transactions(billingFilterParams(pages.transactions)), adminAPI.usage(billingFilterParams(pages.usage)), adminAPI.audit(pages.audit)]); users.value = nextUsers; books.value = nextBooks; tenants.value = nextTenants; availableConfigs.value = nextConfigs; applyPage(transactions, 'transactions', nextTransactions); applyPage(usage, 'usage', nextUsage); applyPage(audits, 'audit', nextAudit) }
async function reloadBilling() { pages.transactions.page = 1; pages.usage.page = 1; await loadGovernance() }
async function onBillingRoleChange() { const selectedUser = users.value.find((user) => Number(user.id) === Number(filters.billing.user_id)); if (selectedUser && filters.billing.role && selectedUser.role !== filters.billing.role) filters.billing.user_id = null; await reloadBilling() }
async function clearBillingFilters() { filters.billing.dates = []; filters.billing.role = ''; filters.billing.user_id = null; filters.billing.tenant_id = null; await reloadBilling() }
async function loadCurrent() { if (activeView.value === 'overview') return refresh(); if (activeView.value === 'production') return loadProduction(); if (activeView.value === 'archives') return loadArchives(); if (activeView.value === 'reconciliations') return loadReconciliations(); return loadGovernance() }
async function openView(view) { activeView.value = view; syncRoute(); await loadCurrent() }
async function drill(target = {}) { const view = target.tab || 'production'; if (view === 'production' && target.status) filters.production.status = target.status; if (view === 'production' && target.model) filters.production.model = target.model; await openView(view) }
async function changePage(name, page) { pages[name].page = page; if (name === activeView.value) await loadCurrent(); else if (name === 'transactions' || name === 'usage' || name === 'audit') await loadGovernance() }
async function openProduction(id) { productionDetail.value = await adminAPI.productionDetail(id); showProduction.value = true }
async function handleProductionAction(action) { const labels = { upscale: '仅重试超分', interpolation: '仅重试插帧', adopt: '采用原片', archive: '仅重试 OSS' }; try { const result = await ElMessageBox.prompt(`“${labels[action]}”将按既有安全流程执行，不会重新提交原始视频。请填写处置原因。`, '二次确认', { inputPattern: /.+/, inputErrorMessage: '必须填写原因', confirmButtonText: '确认处置', cancelButtonText: '取消' }); const data = { confirm: true, reason: result.value, idempotency_key: createClientRequestId() }; if (action === 'adopt') await adminAPI.adoptProductionSource(productionDetail.value.id, data); else if (action === 'archive') await adminAPI.retryProductionArchive(productionDetail.value.id, data); else await adminAPI.retryProductionPostprocess(productionDetail.value.id, { ...data, stage: action }); await openProduction(productionDetail.value.id); await loadProduction(); ElMessage.success(`${labels[action]}已提交`) } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error?.message || '处置失败') } }
async function downloadProduction() { const blob = await adminAPI.productionExport(filters.production); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `production-${new Date().toISOString().slice(0, 10)}.csv`; anchor.click(); URL.revokeObjectURL(url) }
async function createUser() { if (!newUser.username || !newUser.password) return ElMessage.warning('请填写用户名和初始密码'); if (!newUser.tenant_id) return ElMessage.warning('请选择项目分组'); try { await adminAPI.createUser({ ...newUser }); showCreate.value = false; Object.assign(newUser, { username: '', display_name: '', password: '', account_kind: 'creator', tenant_id: null }); await loadGovernance(); ElMessage.success('账号已创建') } catch (error) { ElMessage.error(error?.message || '创建失败') } }
function openUserGroup(row) { selected.value = row; Object.assign(userGroup, { tenant_id: row.tenant_id || null, role: row.tenant_role || 'creator' }); showUserGroup.value = true }
async function saveUserGroup() { if (!selected.value || !userGroup.tenant_id) return ElMessage.warning('请选择项目分组'); try { await adminAPI.setTenantMember(userGroup.tenant_id, selected.value.id, { role: userGroup.role }); showUserGroup.value = false; await loadGovernance(); ElMessage.success('用户分组已更新') } catch (error) { ElMessage.error(error?.message || '分组更新失败') } }
async function openTenant(id) { if (!id) { Object.assign(tenantForm, { id: null, name: '', ai_config_ids: [], default_config_ids: {}, sd2_config_ids: [], price_book_id: null }); showTenant.value = true; return } try { const tenant = await adminAPI.tenant(id); const defaults = {}; for (const item of tenant.configs || []) { if (item.tenant_is_default) defaults[item.service_type] = item.config_id } Object.assign(tenantForm, { id: tenant.id, name: tenant.name, ai_config_ids: (tenant.configs || []).map((item) => item.config_id), default_config_ids: defaults, sd2_config_ids: (tenant.sd2_configs || []).map((item) => item.config_id), price_book_id: tenant.price_book?.id || null }); ensureTenantDefaults(); showTenant.value = true } catch (error) { ElMessage.error(error?.message || '读取分组失败') } }
function openTenantConfigs(tenant) { configTenant.value = tenant; showTenantConfigs.value = true }
async function saveTenant() { if (!tenantForm.name.trim()) return ElMessage.warning('请填写分组名称'); try { if (!tenantForm.id) await adminAPI.createTenant({ name: tenantForm.name.trim() }); else { await adminAPI.updateTenant(tenantForm.id, { name: tenantForm.name.trim() }); const tenant = await adminAPI.tenant(tenantForm.id); await adminAPI.replaceTenantBindings(tenantForm.id, { ai_configs: (tenant.configs || []).map((item) => ({ id: item.config_id, is_default: item.tenant_is_default })), sd2_config_ids: (tenant.sd2_configs || []).map((item) => item.config_id), price_book_id: tenantForm.price_book_id }) } showTenant.value = false; await loadGovernance(); ElMessage.success('分组配置已保存') } catch (error) { ElMessage.error(error?.message || '保存分组失败') } }
function openBalance(row) { selected.value = row; Object.assign(balance, { mode: 'adjust', amount_credits: 0, target_credits: Number(row.balance || 0), reason: '' }); showBalance.value = true }
async function adjustBalance() { if (!selected.value) return; if (balance.mode === 'adjust' && !Number(balance.amount_credits)) return ElMessage.warning('变动积分不能为 0'); try { const idempotency_key = createClientRequestId(); if (balance.mode === 'adjust') await adminAPI.adjustBalance(selected.value.id, { amount_credits: Number(balance.amount_credits), operation: Number(balance.amount_credits) > 0 ? 'grant' : 'debit', reason: balance.reason, idempotency_key }); else await adminAPI.correctBalance(selected.value.id, { target_credits: Number(balance.target_credits), reason: balance.reason, idempotency_key }); showBalance.value = false; await loadGovernance(); window.dispatchEvent(new Event('lmd:balance-changed')); ElMessage.success(balance.mode === 'adjust' ? '积分已变动' : '余额已校正') } catch (error) { ElMessage.error(error?.message || '调整失败') } }
function addPriceItem() { price.items.push({ service_type: 'image', model: '', meter: 'image', unit_price: 0, is_free: false }) }
function openPrice(book) { editingPriceId.value = book?.id || null; Object.assign(price, book ? { name: book.name, status: book.status, items: (book.items || []).map((item) => ({ ...item })) } : { name: '', status: 'draft', items: [] }); if (!price.items.length) addPriceItem(); showPrice.value = true }
async function savePrice() { if (!price.name || !price.items.length) return ElMessage.warning('请填写名称和至少一项计价规则'); try { const payload = { name: price.name, status: price.status, items: price.items.map((item) => ({ ...item, unit_price: Number(item.unit_price || 0) })) }; if (editingPriceId.value) await adminAPI.updatePriceBook(editingPriceId.value, payload); else await adminAPI.createPriceBook(payload); showPrice.value = false; await loadGovernance(); ElMessage.success('价目表已保存') } catch (error) { ElMessage.error(error?.message || '保存失败') } }
let pollTimer
onMounted(async () => { await loadCurrent(); pollTimer = window.setInterval(() => { if (document.visibilityState === 'visible') loadCurrent().catch(() => {}) }, activeView.value === 'overview' ? 60000 : 30000) })
onBeforeUnmount(() => window.clearInterval(pollTimer))
</script>

